styles:
.b-menu {
    container-type: inline-size;
}

.b-menu__list,
.b-menu__sub {
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-menu__link,
.b-menu__label {
    display: block;
    padding: 0.5em 0.75em;
    color: inherit;
    text-decoration: none;
}

.b-menu__link:hover,
.b-menu__link:focus-visible {
    text-decoration: underline;
}

.b-menu__item.is-active > .b-menu__link {
    font-weight: 600;
}

/* A heading is a caption over its group, not something to click. */
.b-menu__label {
    font-weight: 600;
    opacity: 0.75;
}

/* One line: the top level only — nested items belong to the other two layouts. */
.b-menu--line .b-menu__list,
.b-menu--dropdown .b-menu__list {
    display: flex;
    flex-wrap: wrap;
    gap: 0.25em 0.5em;
}

.b-menu--line .b-menu__sub {
    display: none;
}

/* A line whose parents open their children under them, on hover and on keyboard focus. */
.b-menu--dropdown .b-menu__item--parent {
    position: relative;
}

.b-menu--dropdown .b-menu__sub {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    z-index: 10;
    min-width: 12em;
    padding: 0.25em 0;
    color: CanvasText;
    background: Canvas;
    border: 1px solid color-mix(in srgb, currentColor 15%, transparent);
    border-radius: 0.5em;
    box-shadow: 0 0.5em 1.5em color-mix(in srgb, CanvasText 12%, transparent);
}

.b-menu--dropdown .b-menu__item--parent:hover > .b-menu__sub,
.b-menu--dropdown .b-menu__item--parent:focus-within > .b-menu__sub {
    display: block;
}

/* Columns for a footer: each top item is the heading of its column, its children below it. */
.b-menu--columns .b-menu__list {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 12em), 1fr));
    gap: 1.5em;
}

.b-menu--columns .b-menu__list > .b-menu__item > .b-menu__link,
.b-menu--columns .b-menu__list > .b-menu__item > .b-menu__label {
    padding: 0 0 0.5em;
    font-weight: 600;
    opacity: 1;
}

.b-menu--columns .b-menu__sub .b-menu__link,
.b-menu--columns .b-menu__sub .b-menu__label {
    padding: 0.25em 0;
}

/* Narrow — a phone, or a column of the layout: the line becomes a list, and a dropdown's
   children stand under their parent instead of floating over the page. The width of the
   block decides, not the window: the same menu may sit in a wide header and a narrow aside. */
@container (max-width: 36em) {
    .b-menu--line .b-menu__list,
    .b-menu--dropdown .b-menu__list {
        flex-direction: column;
    }

    .b-menu--dropdown .b-menu__sub {
        display: block;
        position: static;
        min-width: 0;
        padding: 0 0 0 1em;
        color: inherit;
        background: none;
        border: 0;
        box-shadow: none;
    }
}
